(()=>{const zh=document.documentElement.lang.startsWith('zh'),keys=['crack','load','opening','mode'],el=Object.fromEntries(keys.map(k=>[k,document.getElementById('M03-'+k)]));let cur={};const C=a=>8*a*a*a/(70000*20*8),G=(P,a)=>12*P*P*a*a/(70000*400*8)*1000;function draw(){const a=+el.crack.value,load=+el.load.value,opening=+el.opening.value,mode=el.mode.value,P=mode==='load'?load:opening/C(a),d=P*C(a),g=G(P,a);cur={crack:a,load,opening,mode,force:P,actualOpening:d,releaseRate:g,ratio:g/300};['crack','load','opening'].forEach(k=>document.getElementById('M03-'+k+'-value').textContent=cur[k].toFixed(k==='opening'?3:1));const calc=x=>G(mode==='load'?load:opening/C(x),x),max=Math.max(600,calc(25),calc(60))*1.1,X=x=>85+(x-25)/35*620,Y=y=>290-y/max*240;let s='<rect width="800" height="360" fill="#f5f8f8"/>';for(let x=25;x<=60;x+=5)s+=`<line x1="${X(x)}" x2="${X(x)}" y1="45" y2="290" stroke="#dde5e6"/><text x="${X(x)}" y="312" text-anchor="middle">${x}</text>`;for(let i=0;i<=4;i++){const yy=max*i/4;s+=`<text x="75" y="${Y(yy)+5}" text-anchor="end">${yy.toFixed(0)}</text>`}let path='';for(let x=25;x<=60;x+=.25)path+=(x===25?'M':' L')+X(x)+','+Y(calc(x));s+=`<path d="${path}" fill="none" stroke="#186c94" stroke-width="3"/><line x1="85" x2="705" y1="${Y(300)}" y2="${Y(300)}" stroke="#188777" stroke-dasharray="6 4"/><circle cx="${X(a)}" cy="${Y(g)}" r="7" fill="#d27839"/><text x="90" y="25">${zh?'绿虚线：阻力300 J/m²':'Green dashed: resistance 300 J/m²'}</text><text x="400" y="345" text-anchor="middle">${zh?'裂纹长度 / mm':'Crack length / mm'}</text><text transform="translate(20 175) rotate(-90)" text-anchor="middle">G / J m⁻²</text>`;document.getElementById('M03-plot').innerHTML=s;document.getElementById('M03-values').textContent='P='+P.toFixed(3)+' N · δ='+d.toFixed(4)+' mm · G='+g.toFixed(2)+' J/m² · G/Gc='+(g/300).toFixed(3);return {...cur}}function set(p){keys.forEach(k=>{if(k in p)el[k].value=p[k]});return draw()}function reset(){return set({crack:30,load:78.9,opening:1.521,mode:'load'})}keys.forEach(k=>el[k].addEventListener(k==='mode'?'change':'input',draw));document.getElementById('M03-reset').addEventListener('click',reset);window.CourseLab={set,state:()=>({...cur}),reset,destroy(){}};reset()})();